lectedPiece.composer.split(' ').slice(-1)[0].toUpperCase()}</small></div><div className="piece-meta"><div><span>Progress</span><strong>{selectedPiece.progress}%</strong></div><div className="piece-progress"><span style={{ width: `${selectedPiece.progress}%` }} /></div><button className="text-button" onClick={() => setIsSessionActive(true)}>Practice now <span aria-hidden="true">-&gt;</span></button></div></> : <div className="empty-focus"><p className="eyebrow">CONTINUE PRACTICING</p><h2>Choose a piece to begin</h2><p className="muted">Add something to your repertoire and make it your focus.</p><button className="text-button" onClick={() => setView('Repertoire')}>Manage repertoire -&gt;</button></div>}</section><section className="panel week-panel"><div className="panel-heading"><div><p className="eyebrow">YOUR WEEK</p><h2>Keep your rhythm</h2></div><span className="target-badge">{Math.round(thisWeekSeconds / 60)} / 180 min</span></div><div className="week-chart">{thisWeek.map((item, index) => <div className="day-column" key={`${item.day}-${index}`}><div className="bar-track"><span className={item.minutes ? 'bar filled' : 'bar'} style={{ height: `${item.minutes ? Math.max(18, Math.min(112, item.minutes * 1.7)) : 8}px` }} /></div><small>{item.day}</small></div>)}</div><p className="chart-caption"><span className="dot" /> Practice minutes <span className="caption-muted">From your saved sessions</span></p></section></div><section className="repertoire-section"><div className="section-heading"><div><p className="eyebrow">MY REPERTOIRE</p><h2>Pieces in progress</h2></div><button className="text-button" onClick={() => setView('Repertoire')}>Manage repertoire <span aria-hidden="true">-&gt;</span></button></div><div className="piece-list">{repertoire.slice(0, 4).map((piece) => <button className={`piece-row ${selectedPiece?.title === piece.title ? 'selected' : ''}`} key={piece.id ?? piece.title} onClick={() => setSelectedPiece(piece)}><div className={`piece-thumb ${piece.tone}`}>{piece.symbol}</div><div className="piece-name"><strong>{piece.title}</strong><span>{piece.composer}</span></div><span className="level-pill">{piece.level}</span><div className="row-progress"><span>{piece.progress}%</span><div className="progress-line"><span style={{ width: `${piece.progress}%` }} /></div></div><span className="row-arrow" aria-hidden="true">-&gt;</span></button>)}</div></section></>}
