iv className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setIsAdding(false) }}><section className="add-modal" role="dialog" aria-modal="true" aria-labelledby="add-piece-title"><button className="modal-close" aria-label="Close" onClick={() => setIsAdding(false)}>x</button><p className="eyebrow">EXPAND YOUR MUSIC</p><h2 id="add-piece-title">Add a piece</h2><div className="add-tabs"><button className={addMode === 'catalog' ? 'active' : ''} onClick={() => setAddMode('catalog')}>Classical catalogue</button><button className={addMode === 'personal' ? 'active' : ''} onClick={() => setAddMode('personal')}>Personal piece</button></div>{addMode === 'catalog' ? <><label className="search-field">Search by title or composer<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Try Chopin, Ballade, Nocturne..." /></label><div className="filter-row"><select value={composer} onChange={(event) => setComposer(event.target.value)} aria-label="Filter by composer"><option>All composers</option>{composers.map((item) => <option key={item}>{item}</option>)}</select><select value={difficulty} onChange={(event) => setDifficulty(event.target.value)} aria-label="Filter by difficulty"><option>All levels</option>{difficulties.map((item) => <option key={item}>{item}</option>)}</select></div><div className="catalog-results">{filtered.map((piece) => <button className="catalog-result" key={piece.id ?? piece.title} disabled={selectedIds.has(piece.id ?? piece.title)} onClick={() => onAdd(piece)}><span className={`piece-thumb ${piece.tone}`}>{piece.symbol}</span><span><strong>{piece.title}</strong><small>{piece.composer} - {piece.level}</small></span><b>{selectedIds.has(piece.id ?? piece.title) ? 'Added' : '+'}</b></button>)}{filtered.length === 0 && <p className="empty-search">No catalogue pieces match those filters.</p>}</div></> : <div className="custom-fields personal-fields"><p>Add something that is not in the shared catalogue. It will stay local to your account and browser.</p><label>Piece title<input value={customTitle} onChange={(event) => setCustomTitle(event.target.value)} placeholder="My new piece" /></label><label>Composer or source<input value={customComposer} onChange={(event) => setCustomComposer(event.target.value)} placeholder="Composer (optional)" /></label><button className="auth-submit" onClick={addCustom} disabled={!customTitle.trim()}>Add personal piece <span aria-hidden="true">-&gt;</span></button></div>}</section></div>}</section>
